<template>
  <div class="appmain">
    <router-view />
  </div>
</template>
<script setup>
import { ref, watch, onMounted, onBeforeUnmount } from "vue";
import { login } from "@/api/all";
import { useRouter } from "vue-router";
import { sm2 } from "./utils/sm2";
import { setToken } from "@/utils/auth";
const router = useRouter();
const loginData = ref({
  password: "SWjs1234",
  userName: "sys",
});
const publicKey =
  "044A2D40A6495769CCD108016E613B030DB01D9FD60AB87D4510BAB2824BE9E8BCF76223A908AD894FF1AAC56BD349BA2E92F4E5556EBEC2BE84A6EE522208365D";
const loginFn = () => {
  const encryptedAccount = sm2.sm2Encrypt(loginData.value.userName, publicKey, 0);
  const encryptedPassword = sm2.sm2Encrypt(loginData.value.password, publicKey, 0);
  login({
    userName: encryptedAccount,
    password: encryptedPassword,
  }).then((res) => {
    console.log(res);
    setToken(res.result.token);
  });
};
loginFn();
</script>

